-- Phase 62: Aatmn Parmar / Redikall point source collection.
-- Faithful transcription from Sakshi.xlsx. These are source statements only,
-- not medical diagnoses, causes, or formula-derived outputs.
START TRANSACTION;
CREATE TABLE IF NOT EXISTS ilb_aatmn_parmar_point_source (
  point_id bigint unsigned NOT NULL AUTO_INCREMENT,
  point_code varchar(80) NOT NULL,
  point_name varchar(500) NOT NULL,
  stated_position_text text NOT NULL,
  stated_foundation_keyword text NOT NULL,
  source_file_name varchar(255) NOT NULL,
  source_locator varchar(1200) NOT NULL,
  source_status enum('SOURCE_RECORDED','NEEDS_SOURCE_REVIEW') NOT NULL DEFAULT 'SOURCE_RECORDED',
  medical_mapping_status enum('NOT_ASSESSED','CANDIDATE','EXACT_MAPPED','REJECTED') NOT NULL DEFAULT 'NOT_ASSESSED',
  created_at datetime(6) NOT NULL DEFAULT current_timestamp(6),
  PRIMARY KEY(point_id),
  UNIQUE KEY uq_ilb_aatmn_point_code(point_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ON DUPLICATE KEY UPDATE point_name=VALUES(point_name),stated_position_text=VALUES(stated_position_text),
 stated_foundation_keyword=VALUES(stated_foundation_keyword),source_file_name=VALUES(source_file_name),
 source_locator=VALUES(source_locator),source_status=VALUES(source_status),medical_mapping_status=VALUES(medical_mapping_status);
COMMIT;